raw.footer:
[data-phase="hero"][data-phase] {
  /* 设计稿六件套：152 / 150(80+16+54) / 60 / 1054x48 / 1096x160 / 40
     （其中提示词行上间距 40 已由用户改为 20，见下） */
  --tpt-hero-top: 152px;
  --tpt-hero-band: 150px;
  --tpt-hero-mark: 80px;
  --tpt-hero-mark-gap: 16px;
  --tpt-hero-title-size: 38px;
  --tpt-hero-title-line: 54px;
  --tpt-hero-card-gap: 60px;
  --tpt-hero-strip-w: 1054px;
  --tpt-hero-strip-h: 48px;
  --tpt-hero-card-w: 1096px;
  --tpt-hero-card-h: 160px;
  /* 用户 2026-09-21 定档 20px（设计稿此处为 40px）。 */
  --tpt-hero-prompt-gap: 20px;
  --tpt-hero-prompt-gap-x: 15px;
  /* 上游 scrollbar-gutter:stable 预留的滚动条槽宽（真机读数：内容盒比列宽窄 8px）-> 补偿量。 */
  --tpt-hero-gutter: 8px;
  /* 上游的对话框宽度权威来源是这个变量（卡片 max-width、首屏文案列 max-width、composerHero 宽度
     三处都从它派生）-> 改这一处，三处一起对齐到 1096。窄窗时退到 100%，不留横向滚动。 */
  --dsh-composer-card-max-width: min(var(--tpt-hero-card-w), 100%);
  /* 顶部条相对卡片的设计稿内收量：(1096 - 1054) / 2 = 21px。缩窄时保持这个内收量（不是按比例缩条宽），
     条与卡片两侧的空隙才不会随窗口宽度漂移。1054 这个字面量只在这里参与运算，不再当宽度上限。 */
  --tpt-hero-strip-inset: calc((var(--tpt-hero-card-w) - var(--tpt-hero-strip-w)) / 2);
  /* 卡片在它那一列里可用的轨道：composerHero 给卡片左右各留 --dsh-composer-side-clearance
     （上游 .uV2eYG_root 的 padding-inline，16px 由 .wSkVaW_root 继承下来）。 */
  --tpt-hero-card-track: calc(100% - 2 * var(--dsh-composer-side-clearance));
  /* 卡片实际宽 = 卡片自己那条 min() 链在**本列**里的落值。顶部条与按钮行是卡片的兄弟 flex item，
     要与之同宽只能复用同一个表达式（条与行的父盒 = composerHero 内容盒，故两处 100% 同基准）。
     这条是本批的正解：卡片宽由上游 --dsh-composer-card-max-width 驱动（左侧栏拖窄对话列 -> 上游
     ResizeObserver 重发 --dsh-conversation-column-width -> 卡片跟缩），我方凡写死宽度或写 100%
     就必然在某一段反超卡片。 */
  --tpt-hero-card-used: min(var(--dsh-composer-card-max-width), var(--tpt-hero-card-track));
}

/* 五、升 0.1.6-alpha.2 的作用域顺平（升版断层判据原文见 implementation/hero-1160x904-tpt-hero）：
   新上游把卡片宽口径挪到 .wSkVaW_body 这一层——卡片 max-width 改由
   clamp(680, 列*0.64, 920) + 32px 推（client.js resolveContentWidth），并且
   --dsh-composer-side-clearance:16px 也只在 body 这一层定义（自定义属性只向下继承，
   所以 hero 根上那条 --tpt-hero-card-used 链引不到 clearance 整链 invalid，顶条宽度 calc 失效）。
   我在 hero 档内把 body 这层的口径盖回"跟对话列、上限 1096"，并把 card-used 链在 clearance
   有效的那一层重新落地，顶条/按钮行才重新与卡片同宽：宽窗回设计稿 1096，窄窗列 < 1096 仍跟着缩
   （用户 09-16 口径）。这套只落在 hero 档，会话态逐字不动。 */
[data-phase="hero"] .wSkVaW_body {
  --dsh-composer-card-max-width: min(var(--tpt-hero-card-w), var(--dsh-conversation-column-width, 100%));
  --dsh-chat-content-width: calc(var(--dsh-composer-card-max-width) - 2 * var(--dsh-composer-side-clearance));
  --tpt-hero-card-track: calc(100% - 2 * var(--dsh-composer-side-clearance));
  --tpt-hero-card-used: min(var(--dsh-composer-card-max-width), var(--tpt-hero-card-track));
}

/* 一、整块从距顶 152px 起排（上游是垂直居中）。
   padding-inline-start 那 8px 是**补偿**上游 .wSkVaW_scrollBody 的 scrollbar-gutter:stable 预留槽：
   它在内容末端预留 8px，内容盒因此比列宽窄 8、align-self:center 的那些块整体左偏 4px
   （真机读数 855 vs 列中心 859）。设计稿要整块水平居中 -> 在起始侧补回同样宽度。
   不用 scrollbar-gutter:auto 去关它：关掉后矮窗里真滚动条出现的那一下会整体跳 8px。 */
[data-phase="hero"] [data-conversation-scroll] {
  justify-content: flex-start !important;
  padding-top: var(--tpt-hero-top);
  padding-inline-start: var(--tpt-hero-gutter);
}

/* 二、第一层 150px：主视觉在上、文案在下，整体居中。HeroShell 无 data 挂点，只能点名 hashed 类。 */
[data-phase="hero"] .pXSMma_root {
  width: 100%;
  height: auto;
  padding: 0;
}
[data-phase="hero"] .pXSMma_stack {
  max-width: none;
  align-items: center;
  gap: 0;
}
[data-phase="hero"] .pXSMma_headline {
  /* 上游是横排（图标在左、文案在右）+ 26px/500；设计稿要上下两层。 */
  flex-flow: column nowrap;
  align-items: center;
  justify-content: flex-start;
  min-height: var(--tpt-hero-band);
  gap: var(--tpt-hero-mark-gap);
  font-size: var(--tpt-hero-title-size);
  font-weight: 700;
  line-height: var(--tpt-hero-title-line);
}
[data-phase="hero"] .pXSMma_fishHitbox {
  width: var(--tpt-hero-mark);
  height: var(--tpt-hero-mark);
}
/* 主视觉位由 @tpt-work/brand 占（conversation.hero.brand.mark），宿主给的 size 是 34 -> 尺寸归本包管。 */
[data-phase="hero"] .pXSMma_fishHitbox img {
  width: var(--tpt-hero-mark);
  height: var(--tpt-hero-mark);
  object-fit: contain;
}
[data-phase="hero"] .pXSMma_titleGroup {
  gap: 8px;
}
/* 首屏那句文案（用户定档：文案走零补丁自渲，不动 locale 补丁）。上游那一棵是
   span.titleGroup 下两个 span：第一个渲 t("hero.headline")、第二个是 previewBadge
   （client.js:14639-14644），第一个 span 无任何挂点、也不是我方件 -> 隐掉它，由 ::before 自渲
   （字号/字重/行高继承 .pXSMma_headline 那条 38/700/54）。徽章那颗见下一条（2026-09-29 起也隐掉）。
   文案本体与取值机制在 headline.ts（六句句池 + 每次进 hero 随机取一句，用户 2026-09-23 定案）：
   这里只写 var()，**不写兜底句** —— 本表里再抄一句就是"一个事实两个家"（R10），而两条路
   （本表的变量名 / 那句文案）本来就在同一个插件包里：装载成功则 headline.ts 必然先写值，
   装载失败则本表也整个没注入（隐掉上游那句的规则同样不在），兜底句没有能生效的场合。
   代价记进账本：这行字不再走 locale 词典（英文语种下也是这句中文），换文案 = 改 headline.ts 的句池。 */
[data-phase="hero"] .pXSMma_titleGroup > span:first-child {
  display: none;
}
/* 上游那颗「预览版」徽章（titleGroup 的第二个 span，文案 = 上游 locale 的 hero.preview）：
   用户 2026-09-29 口径去掉。它是**上游的件**、titleGroup 里没有任何 data 挂点 -> 只能按 CSS module
   的 hashed 类点名（同 .pXSMma_titleGroup 那条纪律，升版复核清单在 hero 账本）。只摘它这一颗，
   不接管它的样式：display:none 之后那颗 span 与它的文案一起不在布局里。
   注意：本表是**随产物发布的字符串** -> 注释里不许出现反引号（写上去当场 TS 语法错），
   也不许出现图标性字形（tpt/icon-glyph 不豁免字符串字面量，行内一律写 -> 或裸词）。 */
[data-phase="hero"] .pXSMma_previewBadge {
  display: none;
}
[data-phase="hero"] .pXSMma_titleGroup::before {
  content: var(--tpt-hero-headline);
  white-space: nowrap;
}
/* 上游留的空 body 层会在 150 之后再加 12px 间隙，设计稿里没有这一层。 */
[data-phase="hero"] .pXSMma_body {
  display: none;
}

/* 三、对话框列：上游 gap 8 会同时作用到每一段，改成逐段自己给，才能同时满足 60 与 0。 */
[data-phase="hero"] .wSkVaW_composerHero {
  gap: 0;
  padding-bottom: 0;
}
/* 「选择项目」那条本来就是卡片正上方的兄弟节点（implementation/hero-hide-agent-mode-picker 后行内只剩工作区 chip）-> 只做设计稿那块皮。
   圆角圆的是**朝上的两角**（左上 / 右上）：这条贴在卡片头顶，下沿与卡片上沿重合、看不见，
   朝外可见的那条边在上方 -> 24px 给上两角，下两角归零才不与卡片的圆角打架。
   （设计稿原文写的是 0 0 24px 24px，用户 2026-09-15 更正：反了，要左上 + 右上。）
   宽度 = 卡片实际宽再两侧各内收 21（不是设计稿那个 1054 字面量）：卡片会随对话列缩
   （上游 --dsh-composer-card-max-width 是 min(1096, 100%)），写死 1054 时列一窄这条就**盖过卡片**
   —— 用户 2026-09-16 报的「拖宽左侧栏后这一行比底下对话框宽」就是它：列 < 1128 起卡片跟缩、条不跟
   （真机对照：卡片 1043 时条仍是 1054，反超 11px）。宽窗下卡片 = 1096 -> 条 = 1096 - 42 = 1054，
   与设计稿逐字相同；缩窄时两侧内收恒为 21，条与卡片同步。 */
[data-phase="hero"] .wSkVaW_heroWorkspaceRow {
  box-sizing: border-box;
  align-self: center;
  width: calc(var(--tpt-hero-card-used) - 2 * var(--tpt-hero-strip-inset));
  height: var(--tpt-hero-strip-h);
  margin-top: var(--tpt-hero-card-gap);
  padding: 0 20px;
  background: #f8f8f9;
  border-radius: 24px 24px 0 0;
}
/* 深色档那一分支：底色比对话框卡片**再深一档**（用户 2026-09-16 口径：深色主题下这条比对话框深一点）。
   卡片底 = 上游 --dsw-specific-input-major（dsh 深色档 = bluish-850 = #2c2c2e，真机实测 rgb(44,44,46)），
   而 dsh 的深色层级是 950(页面底) -> 875(layer-1) -> 850(layer-2 = 卡片) -> 800(layer-3) **逐层变浅**：
   layer-2 与卡片同色（零对比）、layer-3 反而更浅 -> "深一档"唯一对位的现成令牌是 layer-1 = #232324。
   不把它写成浅色档的默认值：浅色档 layer-1 = #fff，会把稿上那条浅灰洗白 -> 只在档位信号下覆盖，
   上面那行 #f8f8f9 逐字不动（浅色档零风险）。选择器带档口 -> 会话态那条同名行不受影响；
   特异性 (0,3,1) > 上面那条 (0,2,0)，胜负不依赖 style 标签的注入顺序。
   顺带解掉一处对比度：行内那颗 WorkspaceChip 上游只给字色 --dsw-alias-state-business-primary、
   自带底色为空（.yAWgPa_chip），原先压在近白的 #f8f8f9 上偏淡，压深底后恢复正常 -- chip 本身不动。 */
body[data-ds-dark-theme] [data-phase="hero"] .wSkVaW_heroWorkspaceRow {
  background: var(--dsw-alias-bg-layer-1);
}
[data-phase="hero"] [data-composer-card] {
  box-sizing: border-box;
  height: var(--tpt-hero-card-h);
}
/* 卡片定高后让输入区吃掉剩余高度，工具行才落在底边（否则底部空一截）。 */
[data-phase="hero"] [data-composer-card] > [data-input-scroll] {
  flex: 1 1 auto;
}

/* 四、四个快捷提示词。这个 dock 槽在会话态也渲染 -> 默认整行不给位置，只在 hero 档落地。
   槽壳是 display:contents（renderer 的 ANCHOR_STYLE）-> 本行直接成为对话框列的 flex item，
   用 order 排到输入卡片之后。
   宽度与卡片取同一个值（--tpt-hero-card-used）：这一行与卡片是 composerHero 的兄弟 flex item，
   写 100% 会连左右 clearance 一起吃掉 -> 比卡片宽 32（同顶部条那条缺陷的另一分支，用户看的是顶部条，
   这一行在窄列下同样超出卡片底边）。 */
[data-tpt-hero-prompt-row] {
  display: none;
}
[data-phase="hero"] [data-tpt-hero-prompt-row] {
  order: 3;
  align-self: center;
  box-sizing: border-box;
  width: var(--tpt-hero-card-used);
  margin-top: var(--tpt-hero-prompt-gap);
  display: flex;
}
[data-tpt-hero-prompts] {
  align-items: center;
  gap: var(--tpt-hero-prompt-gap-x);
  display: flex;
}
[data-tpt-hero-prompt] {
  box-sizing: border-box;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border: 0.5px solid var(--dsw-alias-border-l2);
  /* 30px（用户 2026-09-15 定档，原设计稿写 999px）。按钮实高 38px -> 上下两角半径之和 60 > 38，
     CSS 会按比例把四角一起缩到 f = 38/60 -> 实际生效 19px = 整高一半，观感仍是满圆胶囊。
     写 30 不写 19 是照用户给的数落值；要"真的变小圆角"得给一个小于 19 的数。 */
  border-radius: 30px;
  /* dsh 无 layer 全局 *:before:after{corner-shape:…superellipse(1.5)} 会把满圆胶囊两端
     画成超椭球，观感像椭圆（用户验收报的，同 avatar/switch/state-dot 那批）。显式 round
     （引擎 = superellipse(1)）压回正圆胶囊。特异性 (0,2,0) > 全局星号的 (0,0,1)，同为无 layer
     作者来源 -> 不必 !important（此处不是 Tailwind 工具类，不碰 @layer 那套）。 */
  corner-shape: round;
  background: var(--dsw-alias-bg-base);
  color: var(--dsw-alias-label-primary);
  font-family: inherit;
  font-size: 14px;
  line-height: 20px;
  white-space: nowrap;
  cursor: pointer;
  display: inline-flex;
}
[data-tpt-hero-prompt]:hover {
  background: var(--dsw-alias-interactive-bg-hover);
}
[data-tpt-hero-prompt] svg {
  flex: none;
  display: block;
} | :root{--shiki-foreground:var(--dsw-alias-label-primary);--shiki-background:var(--dsw-alias-markdown-code-block);--shiki-token-constant:#1c7ed6;--shiki-token-string:#2f9e44;--shiki-token-comment:#868e96;--shiki-token-keyword:#d6336c;--shiki-token-parameter:#e8590c;--shiki-token-function:#6741d9;--shiki-token-string-expression:#2b8a3e;--shiki-token-punctuation:#495057;--shiki-token-link:#1971c2}body[data-ds-dark-theme]{--shiki-token-constant:#4dabf7;--shiki-token-string:#69db7c;--shiki-token-comment:#adb5bd;--shiki-token-keyword:#faa2c1;--shiki-token-parameter:#ffa94d;--shiki-token-function:#b197fc;--shiki-token-string-expression:#8ce99a;--shiki-token-punctuation:#ced4da;--shiki-token-link:#74c0fc} | /* 一、两张卡**共用这一条规则**（需求 2.6 那句"模式的子菜单和它们样式一样"由同一条选择器列表保证，
   不靠两处写成一样 —— 两处各写一份就是两份口径，改一处就漂）。
   本表**不隐藏上游那颗加号**：既不再把它 display:none（那是"我渲替代那颗"旧架构的配套，删架构时
   漏删它 = 把唯一那颗加号藏掉 = 界面一颗都不剩，业主三轮"加号没了"的真凶），也不给它套任何
   尺寸/配色。那颗按钮原样由上游渲，点击由 trigger.ts 的 capture 拦截器接管 → 本包只渲两张浮层卡。
   （另有一条把加号所在那一工具行右移 5px 的规则，见下——那是**整行**平移，不作用于按钮本身。） */
[data-tpt-plus-menu],
[data-tpt-plus-submenu] {
  box-sizing: border-box;
  position: fixed;
  max-height: min(60vh, 420px);
  overflow-y: auto;
  padding: 4px;
  border-radius: 12px;
  background: var(--dsw-specific-menu, var(--dsw-alias-bg-layer-1));
  box-shadow: var(--dsw-elevation-prominent);
}
/* 两张卡的差异只有两处：宽与叠层序（子卡压主卡：窄窗下两者可能横向重叠）。 */
[data-tpt-plus-menu] {
  width: 204px;
  z-index: 1100;
}
[data-tpt-plus-submenu] {
  width: 293px;
  z-index: 1101;
}
/* 模式子菜单单独收窄：点名 openEntry.key === 'mode' 打到容器上的 data-tpt-plus-submenu-for
   属性 → 只有【模式】那颗改窄，其余子菜单（Agent / 技能 / 连接器）仍走共用那条宽度规则不变。
   选择器不点 hash 上游类，命中只靠本包自己写的属性。 */
[data-tpt-plus-submenu][data-tpt-plus-submenu-for="mode"] {
  width: 216px;
}
/* switch 型子菜单收窄（2026-09-22 用户口径：「插件子级菜单如果是 switch 类型的，子级菜单整体宽度调整为
   232px」）。判据落在**类型**上（插件在 descriptor 里自报的 type），不点分组 key —— 第三方插件将来再加一个
   switch 组，这条自动管到；与上面那条按 key 点名的 mode 规则是两个判据，别合并。
   属性由 menu-surface 打在子卡上（openEntry.type），本表只读它。 
   注意：本表是模板串：注释里不许出现反引号（会把模板串截断，tsc 报 TS1005）。 */
[data-tpt-plus-submenu][data-tpt-plus-submenu-type="switch"] {
  width: 232px;
}

/* hover 桥：子卡与主卡之间那条缝。指针跨缝会先命中 body，主卡的 pointerleave 就会关掉子卡。
   用 ::before 把缝填成子卡自己的命中区（不改变视觉，只延长命中）。 */
[data-tpt-plus-submenu]::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  right: 100%;
  width: 6px;
}

/* 工具行整体右移：加号那颗与权限那颗在同一行（顺序：加号 → 隐藏 input → 权限那格，
   判据见 trigger.ts 文件头）。
   业主 2026-09-18 改判：**不再用 :has(> button[aria-label=...]) 那条右移 5px**（那要往 flex
   容器侧塞内边距、依赖加号直接子是那颗按钮），改**直接改上游 .uV2eYG_row 的左右 padding**
   （业主原话「直接把 uV2eYG_row 这个样式类的左右 padding 改成 2px 20px 20px」）。该类的上游原值
   是 padding:2px 8px 6px，改后水平 20px → 加号与权限一起右移、右侧 trailing 也对齐 20px。
   注意：**点名了带 hash 的上游类名**（uV2eYG_row）——这违反本表「不点名 hash 上游类」的通用纪律，
   是业主点名的刻意取舍：上游升版若该类名漂移会**静默失配**（无报错），已写进账本「上游升级时重看」节，
   styles.test.ts 那条 hash 纪律一并改为「唯一允许的点名就是 uV2eYG_row」。 */
:where([data-composer-card]) .uV2eYG_row {
  padding: 2px 20px 20px;
}

/* 四、行：图标位 + label + 右侧状态位。高度固定 32（子菜单顶边对位靠它，见 placement.ts）。 */
[data-tpt-plus-row] {
  box-sizing: border-box;
  width: 100%;
  min-height: 32px;
  padding: 0 8px;
  border: none;
  border-radius: 8px;
  background: transparent;
  color: var(--dsw-alias-label-primary);
  font-size: 13px;
  line-height: 20px;
  text-align: start;
  display: flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}
[data-tpt-plus-row]:hover:not([disabled]) {
  background: var(--dsw-alias-interactive-bg-hover);
}
[data-tpt-plus-row][disabled] {
  color: var(--dsw-alias-label-tertiary);
  cursor: default;
}
[data-tpt-plus-row] > svg {
  flex: none;
  display: block;
  color: var(--dsw-alias-label-secondary);
}
[data-tpt-plus-label] {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* 子菜单里那行的第二行描述（Agent/技能都有）：压在 label 下面，同一列。 */
[data-tpt-plus-row-body] {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
[data-tpt-plus-desc] {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--dsw-alias-label-tertiary);
  font-size: 12px;
  line-height: 16px;
}
[data-tpt-plus-chevron] {
  flex: none;
  color: var(--dsw-alias-label-tertiary);
}
[data-tpt-plus-hint] {
  flex: none;
  color: var(--dsw-alias-label-tertiary);
  font-size: 12px;
}

/* 五、分组分割线：由分组自己上下各带一条（不是绝对定位的线），
   所以 Agent / 技能 / 连接器 少任何一条，线的位置自动跟着变——需求 4 那句
   "下方的分割线根据实际情况放置"于是天然成立，不需要任何计算。 */
[data-tpt-plus-hairline] {
  height: 0;
  margin: 4px 8px;
  border-top: 0.5px solid var(--dsw-alias-border-l3);
}

/* 五·一、搜索行内边距（Agent 与 技能 两枚可搜子菜单共用；搜索框本体走 Input 原语，见五·二）。 */
[data-tpt-plus-search-row] {
  padding: 2px 8px 6px;
}

/* 五·二、【子菜单】的行与搜索框（需求方 2026-09-18 口径：行高 52px、搜索框用 Input 原语；
   2026-09-22 用户口径：**行与行之间不加间距**，原「行间 8px」那条删掉）。
   作用域钩子 data-tpt-plus-sub-row 由**子菜单的条目行共用**（插件贡献的四种 picker 行 + 内置头段
   【添加本地文件】那两条），仍保留 data-tpt-plus-row 吃共享行样式；【模式】那两行不挂它
   （它自带图标 + Switch，形态与这些条目行不同族）。 */
[data-tpt-plus-submenu] [data-tpt-plus-sub-row] {
  min-height: 52px;
}
/* 五·二·乙、插件子菜单的**行滚动区**（2026-09-22 用户口径：「子级菜单展示全部菜单，不再是默认 5 个，
   但是仍然展示 5 个，超过 5 个出现滚动条；最底下的查看全部仍保留」）。
   三件事各归各位：① 列表**全渲**（不再切片，见 plus-contrib 的 ContribSubmenu）；② 这一格按"一屏五行"
   封顶 + 自身滚动条 → 一屏还是 5 行；③ 搜索行在它上面、分割线与【查看全部】在它下面 → 那两处不跟着滚（footer 是"去插件页"的出口，滚出视野就没意义了）。
   高度 = 行高 × 一屏行数（两个数都在 placement.ts，本表插值 → 行高改了这里跟着改，不会两处漂）。 */
[data-tpt-plus-rows] {
  max-height: 260px;
  /* 注意：两条轴都要点名。只写 overflow-y: auto 时 overflow-x 的 visible 会计算成 auto，行内容
     哪怕只多出几像素也长出一条**横向滚动条**，它吃掉 8px 高度，一屏只剩 4.8 行（就不是需求方那句
     "仍然展示 5 个"了）。真机读数（连接器那组、232px 宽）：scrollWidth 219 > clientWidth 216、
     clientHeight 252 而 max-height 260。显式 overflow-x: hidden 关掉横条，行内容各自省略号收口。 */
  overflow-x: hidden;
  overflow-y: auto;
}
/* 五·二·甲、（2026-09-21 删除）原这里是 Agent 子菜单行首图标那一族规则（data-tpt-plus-agent 的
   两列 grid、data-tpt-plus-agent-glyph 的 16×16 图标、禁用行的图标置灰）与底部【查看全部Agent】
   的两条（14px 收口 + 292px 滚动区）—— 内置 Agent 子菜单随 agent-roster.ts 一起退场，Agent 组改由
   插件贡献（走共用行样式与共用 footer），这些钩子不再有生产者。 */
/* 五·三、技能子菜单底部【查看全部技能】：16px / 400、文字与其右侧箭头**整组居中**（需求方 2026-09-18 口径）。
   通用 [data-tpt-plus-label] 是 flex:1 → label 顶到最左；这里把它改回按内容收缩（flex:none），
   再让行 justify-content:center → 「文字 + 右侧箭头」作为一个整体居中，箭头仍紧贴文字右侧。 */
[data-tpt-plus-submenu] [data-tpt-plus-viewall] {
  justify-content: center;
  font-size: 16px;
  font-weight: 400;
  /* footer 行挂着 data-tpt-plus-sub-row(min-height 52px)——那是「可搜子菜单」条目行高，对 24px 的
     「查看全部」footer 太高 → 收到 24px（与 line-height 同高；本选择器 specificity 与 sub-row 同权重、
     写在此后 → 覆盖）。 */
  min-height: 24px;
}
[data-tpt-plus-submenu] [data-tpt-plus-viewall] [data-tpt-plus-label] {
  /* 收缩到内容宽（保居中），但**允许在容器不够宽时被压**：插件名很长的那种
     【查看全部<label>】原来会顶出卡右缘，而卡自身是 overflow-y:auto 的滚动容器
     （overflow-x 随之算成 auto）会让整张子卡长出一条横向滚动条。用户口径 2026-09-23：
     子级菜单不出横向滚动条，展示不下就省略号。收缩因子给 0、基准宽按内容取（auto），
     与那条按内容收缩的居中口径不冲突。 */
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tpt-plus-sub-search {
  display: block;
  width: 100%;
}
[data-tpt-plus-submenu] [data-tpt-plus-search-row] input {
  width: 100%;
}
/* 【查看全部技能】footer：居中，label + 箭头并排（箭头紧贴文字右侧，不再两端布局）；
   上方分割线用通用 data-tpt-plus-hairline，天然贴着 footer。
   需求方 2026-09-18：字号 16 / 字重 400 / 居中展示。 */
[data-tpt-plus-viewall] {
  justify-content: center;
  gap: 4px;
  font-size: 16px;
  font-weight: 400;
}
[data-tpt-plus-viewall] [data-tpt-plus-label] {
  flex: 0 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* 六、子菜单空态那一行（不可点，只说明"这里没有可选的"）。 */
[data-tpt-plus-empty] {
  padding: 8px;
  color: var(--dsw-alias-label-dimmed);
  font-size: 12px;
  text-align: center;
}

/* 七、模式那两行：label 左 + Switch 右（需求 2.6）。Switch 用身份包那颗，这里只管布局。 */
[data-tpt-plus-switch-slot] {
  flex: none;
  display: inline-flex;
  align-items: center;
}

/* 八、模式状态条：工具行末尾（权限 tag 旁）的模式 tag（需求 3-6；2026-09-20 改版）。
   两颗（计划 / 目标）由同一个组件 mode-status.tsx 出，皮**照抄权限 tag**
   （dsh-client-ui-permission-presets 的权限 tag 根类）：透明底 + label-secondary 文字 +
   13px/500 + 高 28 + 圆角 24 + padding: 0 4px 0 8px + 内距 4px，hover 只换背景
   --dsw-alias-interactive-bg-hover（文字色不动）—— 需求方 2026-09-20 原话「计划和模式 tag 都改成
   透明背景色，样式包括字体颜色和权限的 tag 保持一致（包括 hover 时的样式）」。
   渲在 conversation.input.left 槽位、该工具行内，inline-flex 与同行兄弟并排。 */
[data-tpt-mode-tags] {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: 8px;
}
[data-tpt-mode-tag] {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
  max-width: 220px;
  height: 28px;
  padding: 0 4px 0 8px;
  border-radius: 24px;
  border: none;
  background: transparent;
  color: var(--dsw-alias-label-secondary);
  font-size: 13px;
  font-weight: 500;
  line-height: 20px;
  white-space: nowrap;
  cursor: default;
  transition: background 0.12s ease;
}
/* 悬停只换背景（与权限 tag 逐字同款）；文字色维持次级色不动。 */
[data-tpt-mode-tag]:hover {
  background: var(--dsw-alias-interactive-bg-hover);
}
/* 待捕获：目标模式已开、目标还没立。只做细微视觉区分（半透明），形状/边框与常驻完全一致（无虚线）。 */
[data-tpt-mode-tag-armed] {
  opacity: 0.8;
}
[data-tpt-mode-tag-label] {
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  overflow: hidden;
}
/* 左侧那格：图标与关闭号**共用同一个 14×14 槽** —— 需求方 2026-09-20「把关闭按钮放到 hover 时替换掉
   文本左边的小图标，而不是一直在 tag 文本右边占位」。两枚都绝对定位叠在同一格，靠 opacity 换班。 */
[data-tpt-mode-tag-slot] {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 14px;
  height: 14px;
}
[data-tpt-mode-tag-glyph],
[data-tpt-mode-tag-close] {
  position: absolute;
  inset: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: opacity 0.12s ease;
}
/* 图标 14px（照抄权限 tag 那条图标尺寸规则）；供稿 glyph 的 viewBox 是 20 格，靠 svg 尺寸缩。 */
[data-tpt-mode-tag-glyph] svg {
  width: 14px;
  height: 14px;
}
[data-tpt-mode-tag-glyph] {
  color: currentColor;
  opacity: 1;
}
/* 关闭号：常态占着同一格但透明（与旧版一样，隐藏时仍可点、可键盘聚焦）。 */
[data-tpt-mode-tag-close] {
  width: 14px;
  height: 14px;
  padding: 0;
  border: none;
  background: transparent;
  color: currentColor;
  cursor: pointer;
  opacity: 0;
}
/* 悬停 tag 本体（含待捕获那枚）或键盘聚焦关闭号：图标让位、关闭号落进同一格。 */
[data-tpt-mode-tag]:hover [data-tpt-mode-tag-glyph],
[data-tpt-mode-tag-slot]:focus-within [data-tpt-mode-tag-glyph] {
  opacity: 0;
}
[data-tpt-mode-tag]:hover [data-tpt-mode-tag-close],
[data-tpt-mode-tag-slot]:focus-within [data-tpt-mode-tag-close] {
  opacity: 1;
}
[data-tpt-mode-tag-error] {
  color: var(--dsw-alias-state-error-primary);
  font-size: 12px;
  line-height: 20px;
}
/* 五·四、（2026-09-21 删除）原这里是「已选中 Agent 的面条 tag」那一族规则（data-tpt-plus-attach
   胶囊本体、hover 文本高亮、14×14 图标、hover 才浮现的关闭 ×）—— AgentAttachChip 随内置 Agent 组
   整条退场（选择语义改由插件贡献的调用令牌承担，工具行 tag 只由 bar 落点的 PlusBarTags 出）。
   同时删掉 styles.test.ts 里钉这条的断言。 */

/* 九、计划 tag 改由我方自渲（mode-status.tsx）→ 上游那颗琥珀 chip **整条藏掉**，否则一颗计划两个 tag。
   锚点用槽位键 [data-slot="conversation.input.plan"]（公开契约，上游换 hash 类名也不受影响）；
   槽位外壳带**行内**样式（dsh-client-ui-renderer 的 SlotOutlet 给每个外壳钉了一条模块级样式常量，
   把外壳摘出布局）→ 作者来源压不过行内样式，必须 !important（本包唯一一处，同 @tpt-work/hero 那条的理由）。
   连带收益：本表从此**不再点名任何计划 chip 的 hash 类**（旧版为把它的关闭号改成 hover 浮现，
   点过那颗 chip 自己的两枚 hash 类）。这样本表名点过的上游 hash 类只剩下面那条 uV2eYG_row。 */
[data-slot="conversation.input.plan"] {
  display: none !important;
}

/* 十、工具行贡献头像条（bar 落点；ADR-027 决定 5 补记 + 2026-09-22 七补记改版）。
   每枚 = 一枚 30×30 Avatar（边长与配色走件的 className，本表**不写颜色**）；相邻重叠 8px（后一枚盖住
   前一枚一部分）；tag 上**没有**关闭钮 —— 关闭 = 在加号菜单里取消选中该行。
   本表只管三件几何：组内居中、重叠量、以及把这一条挪到「加号与权限菜单之间」。 */
[data-tpt-plus-bar] {
  display: inline-flex;
  align-items: center;
  /* 需求 6：整条头像组水平居中；需求 4/5 的重叠量由下面那条负边距给，gap 归零免得吃掉它。 */
  justify-content: center;
  gap: 0;
}
[data-tpt-plus-bar-tag] {
  display: inline-flex;
  /* 头像是定尺件，不许被 flex 压缩（30×30 是需求 2 的判据）。 */
  flex: none;
}
/* 第二个起每枚左移 8px：第二枚盖住第一枚、第三枚盖住第二枚（需求 4/5）。 */
[data-tpt-plus-bar-tag] + [data-tpt-plus-bar-tag] {
  margin-left: -8px;
}
/* 落位（需求 3：整组放在加号与权限菜单之间）：DOM 里 conversation.input.left（本组件）排在权限那一格
   .modes **之后**，靠 flex order 把它排到头像条之后，头像条于是落到加号右侧、权限左侧。
   锚点用**公开的槽位键** data-slot="conversation.input.permission"（不点名上游 hash 类）：命中那个
   直接装着权限槽壳的 div（= .modes）。模式 tag 同取 order:1 且 DOM 在 .modes 之后，仍紧随权限那格，
   与改版前同一位次；没有权限格 / 没有头像条时这条规则不改变任何可见顺序。 */
[data-composer-card] div:has(> [data-slot="conversation.input.permission"]) {
  order: 1;
}
[data-composer-card] [data-tpt-mode-tags] {
  order: 1;
} | [data-tpt-sidebar-action]{
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 6px;
  width: 100%;
  height: 38px;
  /* 左右 8px（用户口径）：上游 .newSession 是 8px 16px，我方把 inline 轴收到 8px。
     这个数同时是下面「更多」子项那条对位算式的**第一个加数**，改这里要一起改那里。 */
  padding: 8px;
  margin: 0;
  border: none;
  border-radius: 12px;
  background: transparent;
  color: var(--dsw-alias-label-primary);
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  line-height: 22px;
  overflow: hidden;
  position: relative;
}
[data-tpt-sidebar-action]:hover{
  background: var(--dsw-alias-interactive-bg-hover);
}
[data-tpt-sidebar-action]:active{
  background: var(--dsw-alias-interactive-bg-active);
}
[data-tpt-sidebar-action]:focus-visible{
  outline: 1px solid var(--dsw-alias-border-l3);
  outline-offset: -1px;
}
/* ── 二十一改版：功能页**选中态** ─────────────────────────────────────────────────────
   真值 = 上游 layout store 的 activePanelId（TSX 落成 data-tpt-sidebar-active="true" +
   aria-current="page"）。三个视觉值**逐字照抄上游侧栏面板行的选中态**，不自造观感：
     .hHd-Xa_panelRow.hHd-Xa_panelActive{background:var(--dsw-alias-interactive-bg-active);
       color:var(--dsw-alias-label-primary);font-weight:500}
   （上游 41 枚 --dsw-* 变量里没有专门的 selected token —— interactive 族只有 bg-hover /
   bg-hover-solid / bg-active 三枚，bg-active 就是它自己给"生效中那一行"用的那枚。）
   aria-current="page" 也与上游 PanelRow 同法（dsh-client-ui-sidebar/lib/client.js:116）。
   特异性：选择器前面带 **button** 是有作用的 —— 「更多」子项那条二十改版的规则（子项行把字重定在
   400，见下面 more-items 那段）是 (0,2,0)，本条若也只写两个属性选择器同样是 (0,2,0) 且**写在它之前**
   → 子项选中时字重被吃掉（真机 C2 实测 fw=400）。加上元素选择器升到 (0,2,1) 后**与注入顺序无关**地
   胜出，比"调顺序"更稳（顺序是最脆的契约：谁以后往中间插一条规则就能把它翻掉）。
   同理再给一条 (0,3,1) 的 hover 复合分支：鼠标停在已选中行上仍是选中样，不被 :hover 洗成普通样。 */
button[data-tpt-sidebar-action][data-tpt-sidebar-active="true"]{
  background: var(--dsw-alias-interactive-bg-active);
  color: var(--dsw-alias-label-primary);
  font-weight: 500;
}
button[data-tpt-sidebar-action][data-tpt-sidebar-active="true"]:hover{
  background: var(--dsw-alias-interactive-bg-active);
}
[data-tpt-sidebar-label]{
  white-space: nowrap;
  max-width: 200px;
  overflow: hidden;
}
/* ── 插件自备图标（2026-09-21）─────────────────────────────────────────────────────────
   形状/颜色/尺寸三件都在 TSX 的内联样式里（SeatIcon：mask-image + background:currentColor
   + 16×16），这里只补两件布局：
   - flex-shrink:0 —— 行是 inline-flex，文字带 max-width，图标被压扁会长成一条竖线（蒙版的形状
     一旦不是正方形，视觉上就是"图标坏了"）；
   - display:block —— span 默认 inline，蒙版盒子在 inline 基线下比 16px 高一点，会把行高推歪
     （行高 38px 是一级菜单所有按钮共用的几何，不能由一颗图标带偏）。
   为什么不做 :hover 变色：颜色已经是 currentColor，按钮的 color 由选中态/hover 那几条规则管
   → 图标自动跟随时不需要在这里再列一遍。 */
[data-tpt-sidebar-icon]{
  display: block;
  flex-shrink: 0;
}
/* 一级菜单蓝点（PRD AT-001 / §4.4：自动化任务存在等待确认记录时点亮）。
   只因「自动化任务」那颗（data-tpt-sidebar-badge="true" 由 TSX 只在计数 > 0 时落）。
   几何 = 8px 圆点 + 2px 与底色同色的描边圈；颜色与自动化任务面板那颗「等待确认」状态点同值
   （packages/automation/src/client/main-view.tsx 的 DOT.waiting = #2680e8），两侧观感一致。
   定位相对按钮自身（上方已给 position:relative），钉在右上角；pointer-events:none 不挡点击。
   宽栏与 rail 都生效（rail 只有图标，点依旧钉在右上）。 */
[data-tpt-sidebar-badge]{
  position: absolute;
  top: 7px;
  right: 11px;
  width: 8px;
  height: 8px;
  border-radius: 9999px;
  background: #2680e8;
  box-shadow: 0 0 0 2px var(--dsw-alias-bg-base);
  pointer-events: none;
  z-index: 1;
}
[data-tpt-sidebar-more-row]{
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
  padding: 0 2px 8px;
}
/* 「更多」的包裹层（十九改版：从 Menu 的浮层锚改成 disclosure 的纵向容器）。
   column → 按钮一行、展开的四行紧跟其下，整块进入常规文档流把后续内容下推。 */
[data-tpt-sidebar-anchor="more"]{
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
  width: 100%;
}
/* ── 二十改版：「更多」那颗的**三态图标**（用户 2026-09-14 定档）─────────────────────
   不 hover 恒为三点（按「不hover时始终还是三个点」的字面实现：展开态只要指针离开也回到三点）；
   hover 未展开 = 右向 chevron；hover 且已展开 = 下向 chevron。三颗 svg 都在 DOM 里、只做显隐
   → 纯声明式（切换不触发 React 重渲染，也不依赖 :has()）。展开态读按钮上已有的 aria-expanded
   （TSX 为 a11y 早就写了它，这里复用，不另加状态属性）。
   选择器用类名：图标件 IconProps 只接 size/className，塞不进 data-*；类名是本包自有的
   tpt-sidebar-more-ic-*，与上游 CSS module 的 hashed 名不可能撞。三条规则特异性
   (0,3,0) / (0,4,0) / (0,5,0) 互不覆盖 → 与样式注入顺序无关。
    尺寸口径（用户先定档后反转）：动作条图标统一 16x16。2026-09-14 曾把这两颗 hover 才显的 chevron
    排除在 16 之外（窄 14），真机自测发现 hover 那一瞬首列宽 16 变 14 → 文字左缘左移 2px、且图标高度
    16/14 不一（行抖动）；本轮拍板改回 16 → chevron 与三点、其余一级菜单几何完全同尺寸，hover
    不再位移、也不再抖。TSX 侧两颗箭头现在直接传 ACTION_ICON_SIZE，这里没有例外档位。
    注意：四十三改版：这五条**全部**多挂一个 data-tpt-sidebar-more-hover="icons" 属性选择器 = 宽栏专属
    （五条特异性整体各 +10，相对次序不变 → 仍与注入顺序无关）。rail（侧栏收起）不给那颗按钮写这个
    属性 → 三点在 hover 下一动不动（用户口径「sidebar 收起的时候，更多按钮 hover 的时候不用展示
    收起/展开图标」）。这道门禁不是装饰：rail 虽然根本不渲染那两颗箭头，但「hover 收三点」那条命中
    的是三点自己，不门禁就会让那颗只剩图标的钮在 hover 时变成一个空框。 */
[data-tpt-sidebar-action="more"][data-tpt-sidebar-more-hover="icons"] .tpt-sidebar-more-ic-right,
[data-tpt-sidebar-action="more"][data-tpt-sidebar-more-hover="icons"] .tpt-sidebar-more-ic-down{
  display: none;
}
[data-tpt-sidebar-action="more"][data-tpt-sidebar-more-hover="icons"]:hover .tpt-sidebar-more-ic-more{
  display: none;
}
[data-tpt-sidebar-action="more"][data-tpt-sidebar-more-hover="icons"]:hover .tpt-sidebar-more-ic-right{
  display: inline-flex;
}
[data-tpt-sidebar-action="more"][data-tpt-sidebar-more-hover="icons"]:hover[aria-expanded="true"] .tpt-sidebar-more-ic-right{
  display: none;
}
[data-tpt-sidebar-action="more"][data-tpt-sidebar-more-hover="icons"]:hover[aria-expanded="true"] .tpt-sidebar-more-ic-down{
  display: inline-flex;
}
/* 就地展开的子项列表（二十改版：**三项、无图标**、整块左侧一条边框）。
   边框位置的算式（宽栏；全部相对「更多」按钮左缘 —— 按钮与本列表是同一 column 容器的 100% 宽子级，
   两者左缘重合）：按钮 padding-inline-start 8 + 图标宽 16 → **图标中心 = 16px**
   → margin-inline-start:16px 后本列表那条 1px 左边框正好从图标中间起笔。
   子项文字 padding 13 → 文字左缘 = 16 + 1 + 13 = 30px = 按钮文字左缘（8 + 图标 16 + gap 6）
   → 子项文字与父项文字对齐。这四个数（8 / 16 / 1 / 13）是一组算式，父项那条 padding 或图标尺寸
   一动，这里的 16px 与 13px 就要跟着重算（TopActions.test.tsx ④⑤ 两条判据把等式钉住）。
   注意：四十三改版：这条算式**只属于宽栏那张就地展开**。rail（侧栏收起）不再发 indent="false" ——
   它的子项住在下面那张浮层卡里 → indent 只剩 true 一条分支；原来那条「rail 子项回到居中行」的规则
   同时成了死规则，已一并摘掉。 */
[data-tpt-sidebar-more-items]{
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 2px;
}
[data-tpt-sidebar-more-items][data-tpt-sidebar-more-indent="true"]{
  margin-inline-start: 16px;
  border-left: 1px solid var(--dsw-alias-border-l3);
}
[data-tpt-sidebar-more-items] [data-tpt-sidebar-action]{
  display: flex;
  width: 100%;
  height: 30px;
  padding: 4px 16px 4px 13px;
  justify-content: flex-start;
  font-size: 13px;
  font-weight: 400;
  line-height: 20px;
}
/* ── 四十三改版：rail（侧栏收起）档「更多」的**浮层卡** ─────────────────────────────────
   宽栏那张就地占位的展开（十九改版）在 56px 里没有意义：那里没有可下推的文字，展开只会把整块任务
   列表往下顶。rail 因此改成挂在按钮**右下方**的一张卡 —— TSX 侧 portal 到 body，坐标按锚点矩形量
   （left = rect.right、top = rect.bottom + 4）→ **只有 left/top 是内联的**，其余全在这条规则里。
   底色 / 描边 / 投影引上游已定义的三枚 token（bg-layer-2 + border-l2 + shadow-lv3，正是它那张
   _float_ 浮层用的同一族），我方不自造观感；shadow-lv3 在主题运行期注入的表里，取不到时后面那个
   字面量兜底。z-index 与身份包 Menu、上游浮层同档（50）：它必须盖在右侧内容区之上。
   注意：这条规则的选择器**必须是 more-popover 单独一个属性**。不许图省事写成"子项列表 + 浮层"那种复合
   形式：上面那句「占位列表不许有绝对/固定定位」的判据（TopActions.test.tsx 十九改版那条 not.toMatch）
   是按选择器前缀扫的，复合写法会一头撞进那道门禁 —— 而这两句说的本来就是两种形态。 */
[data-tpt-sidebar-more-popover]{
  position: fixed;
  z-index: 50;
  box-sizing: border-box;
  min-width: 132px;
  max-width: 240px;
  padding: 4px;
  border: 1px solid var(--dsw-alias-border-l2);
  border-radius: 12px;
  background: var(--dsw-alias-bg-layer-2);
  box-shadow: var(--dsw-shadow-lv3, 0 0 1px 0 #0003, 0 0 4px 0 #00000005, 0 12px 32px 0 #00000014);
  /* 横向裁掉（圆角内的溢出），纵向**允许内部滚**：TSX 给这张卡内联了 max-height = 顶边到视口底的余量。
     「更多」那颗住在 panelList **下方**、rail 里已经很贴近窗口下沿，而卡高随**已装插件的席位数**长
     （每行 30px，那由装机决定）→ 不给出口就是最下面几行长出视口底 = 看不见也点不到。宁可在卡里滚，
     也不把"右下方"翻成往上长（那是另一种口径）。 */
  overflow-x: hidden;
  overflow-y: auto;
}
/* 卡里的行**整条继承上面那条子项几何**（30px 高 / 13px 字号 / 400 字重 / 左对齐）→ 与宽栏同一个
   交互形态，选中态那条 (0,2,1) 的规则照样压得住它。只换 padding 的 inline 轴：13px 是宽栏「子项文字与
   父项图标中心对位」那组算式的产物，挂在卡片左缘上没有意义 → 回到卡自己的 4 + 10 = 14px。
   特异性与上面那条同为 (0,2,0) → 靠**写在它后面**取胜（调换顺序 = 把宽栏那 13px 带进卡里）。 */
[data-tpt-sidebar-more-popover] [data-tpt-sidebar-action]{
  padding-inline: 10px;
}
/* ── 二十六改版：插件功能页的**我方承载**（plugin-panel.tsx）─────────────────────
   第三方插件页体改由我方 iframe 承载后，几何必须由我方给：裸 iframe 的默认尺寸是 300×150，
   不给这条就是「点插件菜单 → 右侧出现一个小方块」。量级沿用插件原来那套（实测它们自己的
   .skillsCentralFrame 是 flex:1 / min-width:0 / min-height:0 / border:none，真机 1160×904 撑满主区）
   所以换我方承载后视觉不跳。**只给几何**：颜色与排版留给插件页体自己（那是它自己的产品决定，我方一行
   都不覆盖，免得又造出一个「我方替第三方改样式」的维护负担）。
   注意：这段注释在 JS 模板串内，两个坑都踩过一次——写反引号会当场终止模板串（编译直接红）；写
   箭头/警告这类图标性字形会被 tpt/icon-glyph 门禁判成"图标进产物"。文件名一律裸写、字形一律不用。 */
[data-tpt-plugin-panel]{
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
}
.tpt-plugin-frame{
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  border: none;
  background: transparent;
}
/* 加载失败分支（政策 P-5：不留白）：一句人话居中在原来那一格里。 */
[data-tpt-plugin-panel-error]{
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  flex: 1 1 auto;
  padding: 24px;
  text-align: center;
  color: var(--dsw-alias-text-secondary);
}
/* 「更多」里**未适配**插件那一行：渲的是插件自己的组件（原本长在侧栏底部，按整行设计），放进子项行
   里要能跟着行宽收缩。仍只给几何，且**不摘高度**（留档第 1 条口径）。 */
[data-tpt-plugin-seat="raw"]{
  min-width: 0;
  overflow: hidden;
}
/* 列表 Tabs 行（第 5 件）：**视觉全交官方件**（身份包 barrel 的 Tabs + shadcn line variant，
   选中下划线由 base-ui 的 Tailwind 类供）。2026-09-12 用户口径：去掉自加的 10px 边距与全部
   覆盖样式，本包对 Tabs **零条**样式规则（二十六改版起，连最后那条「IM 档摘内容区」的显隐规则
   曾随那颗占位 tab 一起删除，二十七改版又以正确形态恢复 —— 它不是给 Tabs 上样式，是**借** Tabs 的
   档位属性去摘上游内容区，见下面那段留档与恢复后的那条规则）。
   注意：本注释位于 JS 模板串内，内部**禁止出现反引号**（会终止模板串，编译当场红）。 */
/* 二十六改版（用户 2026-09-16）：这里原本有一条「档位 = IM频道时摘掉上游内容区」的规则，
   随那颗手写「IM频道」占位 tab 一起删除（没有消费方了 = 死 CSS）。**但它换来的四条口径仍然有效，
   本包后面还要反复用**，故原样留档，不要当垃圾再清一遍：
   1. **只摘内容、不摘高度**：「_regionArea」 在侧栏列容器（_root，flex column）里是 flex:1 1 0%
      的撑高件，底部设置区是 flex:0 0 auto 的后继兄弟——整块 display:none 会让它退出 flex 分配，
      设置按钮随即顶上来（用户 2026-09-12 验收口径：两档高度必须一致，设置恒钉底部）。
   2. 摘的对象是**槽的子节点**而不是槽本身：上游那个 [data-slot] div 带内联 style display:contents
      （真机 outerHTML 实测），内联样式压过任何选择器（我方规则 matches() 为 true 却照样不生效），
      而它的子节点无内联样式，命中即隐。
   3. 命中走 :has() 从**祖先**命中（纯声明式：不碰 React 管的节点、重挂载不丢、不写 JS 状态机）。
   4. 类名是 CSS module hashed 前缀 + 语义后缀，按**后缀**匹配（升 dsh 即需复核：implementation/sidebar-top-actions-tpt-sidebar Open items）。
   注意：本注释位于 JS 模板串内，内部**禁止出现反引号**（会终止模板串，编译当场红），也禁止图标性
   字形（tpt/icon-glyph 门禁：模板串里的"注释"是随产物发布的字符串，不是注释）。 */
/* ── 二十七改版（用户 2026-09-16 自测后）：把上面留档那条规则**按原样恢复** ────────────────────
   二十六改版随那颗手写占位 tab 一起删了它（当时没有消费方 = 死 CSS，TopActions.test.tsx 里那条否定式
   判据也这么钉）。现在插件档是**真档位**且它换的是**侧栏内容区**：档位 ≠ 任务时上游那套工作区/项目列表
   要让位给那一档的内容（插件自己渲的那块，或交接期我方的略缩列表）。
   选择器口径**逐字沿用真机验收过的那一条**（git 历史 39f88152 的同一形状，2026-09-12 两档等高验收就是它过的），
   三条口径也都在这条形状里：只摘内容不摘高度（设置区仍钉底部）；摘的是**槽的子节点**（槽本身带内联
   display:contents，命中它也隐不掉）；从**祖先** :has() 命中（纯声明式，不碰 React 管的节点、重挂载不丢）。
   rail 下整行 Tabs 不渲染 → :has() 恒不成立，不需要额外排除。上游若改层级导致断链，症状是"切到插件档
   任务列表还在"（不是白屏），复核锚见 implementation/sidebar-top-actions-tpt-sidebar Open items。
   注意：ADR-030 起档位名不再是字面量 im（ADR-030-plugin-sidebar-tab-content-contract 决策 6），判据改成
   「档位属性在场且不等于 tasks」，所以第二颗带 tab 的插件不用再改这条 CSS。 */
div:has([data-tpt-sidebar-tabs]:not([data-tpt-sidebar-tabs="tasks"])) > [class*="_regionArea"] > [data-slot="sidebar.workspaces"] > *{
  display: none;
}
/* ── 三十二改版（用户 2026-09-16 自测后）：侧栏内容区**只认槽**，未走槽引擎的节点不给位置 ───────
   触发这条的实测：连接器插件（用户从插件市场上传的那份）注册环节已被主权守卫正常改写（门禁流水里有那条），
   但它那个侧栏启动器组件根本不就地渲染——产物里 ensureTopLauncherMount 先 document.createElement 一个
   自造 mount、insertBefore 到 [data-slot="sidebar.workspaces"] 之前，再 createPortal 过去，还挂了
   MutationObserver 守着（节点被移走就重建）。真机读数：_regionArea 的直接子节点里多出一个
   div.mcpConnectorTopMount（268x50，占掉正常一行位），而它**没有 data-slot**。
   判据因此写成结构式，不按插件名或类名点名：
     _regionArea 的合法直接子节点，按构造就是"某个槽的外层 div"（我方补丁那两条 + 上游那条，真机实测
     在场三个子节点、三个都有 data-slot）；没有 data-slot 的直接子节点就是**没经过槽引擎**塞进来的。
   这样不依赖对方的类名与属性名（改名绕不过：它造不出一个真 data-slot），也不写死任何插件名
   （政策 P-4/P-6：判据只看结构，不向插件方提要求、不猜来源）。
   为什么是 CSS 摘掉而不是 JS 摘除节点：对方有 MutationObserver 会立刻重建，删与反删就是军备竞赛加
   CPU 空转；display:none 让它留在 DOM 里（React 的 portal 目标照样存在，不报错）只是不给位置。
   失效方向也想过：这条万一误伤，表现是"侧栏少一块"——所以配了真机判据把三个槽的可见性与等高一起钉住
   （temp/verify-connector-v32.cjs 的 B 段），上游将来若在这层放非槽子节点，那条判据会先红。
   注意：本注释位于 JS 模板串内，禁止反引号（会终止模板串）与图标性字形（tpt/icon-glyph 门禁）。 */
div:has([data-tpt-sidebar-tabs]) > [class*="_regionArea"] > :not([data-slot]){
  display: none;
}
/* ── 十九改版：滚动收口到侧栏**中间那一整块**（用户口径：各折叠面板自己的纵向滚动条去掉，
   改成整个菜单栏一条滚动；顶部品牌行与底部设置区固定，「新建任务」因此常驻顶部）。
   实现 = 把唯一的滚动区域从上游会话列表 「_list」 搬到 「_regionArea」：
     1. 「_regionArea」 由上游的 overflow:hidden 改成 overflow-y:auto（横向仍裁：它带
        margin-left:-4px / margin-right:-12px 的负边距，不裁会冒出横向滚动条）；
     2. 链路上每一段"撑高 + 内滚"的 flex 项全改成**按内容高**（flex:0 0 auto + overflow:visible）。
        这一步是**必需**的、不是顺手清理：滚动容器只会滚它自己的可滚动溢出区，而一个
        flex:1 1 0% + min-height:0 的子项会被夹在可用高度内，内容只是**溢出去压住后面的兄弟**
        （症状 = 「最近」区被上游列表盖住）且外层滚动条压根不出现。
   选择器按 CSS module 的**后缀**匹配（hashed 前缀 + 名字），并且比上游同类名规则多带一层锚，
   特异性 (0,2,0) > 上游 (0,1,0) → 不依赖样式注入顺序。上游改结构即静默失效 = implementation/sidebar-top-actions-tpt-sidebar 复核项。
   注：「[data-slot="sidebar.workspaces"]」 那层带内联 display:contents（真机 outerHTML 实测）→
   它自己不生成盒子，「_root」 才是 _regionArea 的真正 flex 项，所以改 「_root」 才有效。
   旧「IM 档单独 overflow-y:auto」那条被本块**取代**（两档现在共用同一个滚动区域）。 */
div[class*="_regionArea"]{
  overflow-y: auto;
  overflow-x: hidden;
}
/* 工作区浏览块（上游 flex:1 1 0% / min-height:0）→ 按内容高 */
[data-slot="sidebar.workspaces"] [class*="_root"]{
  flex: 0 0 auto;
}
/* 列表这一处两条一起改：_listArea（flex:1）与 _list（flex:1 + overflow-y:auto + scrollbar-gutter）。
   [class*="_list"] 同时命中这两个（_listArea 含子串 _list）→ 这里要的就是同时命中；分组视图与平铺
   视图共用同一个 _list 类（平铺那颗是 clsx(list, flatList)，真读码确认）→ 两种视图一起收口。
   :not([class*="Indicator"]) 是**必要**的排除：拖到列表顶时上游会插一个 bhn1Oq_listTopDropIndicator
   的 span（同带 _list 子串），它不是滚动容器，别顺手把它的 flex/overflow 也改了。
   不会误伤 _panelList（大写 L，子串不匹配，且它在 _regionArea 之外）。 */
[data-slot="sidebar.workspaces"] [class*="_list"]:not([class*="listTopDropIndicator"]){
  flex: 0 0 auto;
  overflow: visible;
}
/* ── 六改版：三区面板（置顶 / 项目 / 最近）────────────────────────────────────────
   两槽的外层 div 是补丁里我方的真 div（不是 slot 锚），它们是上游 _regionArea 的 flex 项，
   故必须 flex:none 不参与伸缩。十九改版后这条的**理由**变了但结论不变：_regionArea 现在是
   唯一滚动容器，flex:none = "按内容高、完整计入可滚动范围"；留 flex 伸缩就会在窗口变矮时被夹扁
   （内容裁掉而滚动条不出现，正是本轮要消掉的那类症状）。
   [!] 本块内所有注释位于 JS 模板串内 → 禁止出现 U+21D2（oxlint tpt/icon-glyph 只抓字符串里的它）。 */
[data-slot="sidebar.region-above"],
[data-slot="sidebar.region-below"]{
  flex: none;
}
[data-tpt-region]{
  display: flex;
  flex-direction: column;
  margin-bottom: 4px;
}
/* 表头 = 折叠钮：几何照抄上游 sectionHeader（36px / r12 / label-tertiary / pad 左 4px），
   它与上游那颗「项目」折叠钮同排时看起来是同一族。 */
[data-tpt-region-header]{
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 4px;
  height: 36px;
  padding: 0 4px;
  margin: 0;
  border: none;
  border-radius: 12px;
  background: transparent;
  color: var(--dsw-alias-label-tertiary);
  font-size: 14px;
  line-height: 20px;
  cursor: pointer;
}
[data-tpt-region-header]:hover{
  background: var(--dsw-alias-interactive-bg-hover);
}
[data-tpt-region-header]:focus-visible{
  outline: 1px solid var(--dsw-alias-border-l3);
  outline-offset: -1px;
}
[data-tpt-region-title]{
  font-weight: 500;
}
/* 内容区**不再自带滚动**（十九改版，用户口径：折叠面板各自的纵向滚动条去掉，改由 _regionArea
   一条滚动容器统一滚）。七改版起两区**空集即整块不渲染**（用户口径），故这里没有「暂无…」占位行的样式。
   旧的两条上限（本块 160px、「最近」40vh）连 「overflow-y:auto」 一起删除 —— 保留上限就等于把
   "面板自己滚"换个写法留下，滚动条会以另一种形态回来。 */
[data-tpt-region-body]{
  overflow: visible;
}
/* ── 四十四改版（用户 2026-09-19）：两区末尾那颗「展开其余 N 个会话 / 收起」─────────────────
   观感**逐字照抄上游那颗同名件**（dsh-client-ui-workspace 的 .xxxx_sessionOverflowButton：
   28px 高 / r8 / 通栏 / 无边框无底 / 12px / label-tertiary，hover 只换 label-secondary、
   **不给 hover 底色**）—— 用户要的就是"dsh 自带那颗"，自造观感会变成两种长相。
   唯一改的是左内边距：上游是 28px，那是给它自己**带缩进**的会话行对位用的；我方两区的行左内边距
   是 4px（二十三改版：标题落在面板标题那条竖线上），这颗跟着行走同一个 4px，右内边距同行的 8px。
   字号 12px 与行内标题的 14px 不同档是刻意的：它是"控件"不是"内容"，与上游一致。 */
[data-tpt-region-overflow]{
  box-sizing: border-box;
   display: block;
   width: 100%;
   height: 28px;
   padding: 0 8px 0 4px;
   margin: 0;
   border: none;
   border-radius: 8px;
   background: transparent;
   color: var(--dsw-alias-label-tertiary);
   font-size: 12px;
   line-height: 20px;
   text-align: left;
   cursor: pointer;
}
[data-tpt-region-overflow]:hover{
  color: var(--dsw-alias-label-secondary);
  background: transparent;
}
[data-tpt-region-overflow]:focus-visible{
  outline: 1px solid var(--dsw-alias-border-l3);
  outline-offset: -1px;
}
/* ── 七改版：「项目」表头整行 hover（用户口径：要和置顶/最近表头的通栏 hover 同款）
   上游 sectionHeader 本体已有 36px / r12 / pad 左 4px，本块只补 hover 底色与手型两条，
   颜色仍引上游 ghost 家族 token。rail 必须排除：rail 下补丁的整行 onClick 被 wide 门禁挡掉、
   折叠钮也不渲染，此时给 hover 反馈就是撒谎（上游 rail 态给 root 加 _rail 类，按后缀命中）。 */

[data-slot="sidebar.workspaces"] [class*="_root"]:not([class*="_rail"]) [data-tpt-projects-header]{
  cursor: pointer;
}
[data-slot="sidebar.workspaces"] [class*="_root"]:not([class*="_rail"]) [data-tpt-projects-header]:hover{
  background: var(--dsw-alias-interactive-bg-hover);
}
/* ── 三十九改版（用户 2026-09-16）：hover 卡内容 ────────────────────────────────────────
   注意：本注释在 JS **模板字符串**里，会原样进编译产物。所以里面
   · 不能出现反引号（会当场终止字面量：vitest 报「Expected a semicolon」，tsc 只给一句语法错）；
   · 不能有"图标性字形"（箭头、警示三角那一类，oxlint 的 tpt/icon-glyph 就地红）。
   引用符号一律用引号或裸名。

   卡片**外壳**不在这里：它就是三点操作面板那张卡（Menu 的 menuSurface 同款：popover 底 + 发丝描边
   + r12 + shadow-lg），宽 400px / 内边距 12px，落位与停留沿用身份包 HoverCard 的那套（右侧 8px、
   500ms、两轴都夹取）。一处改动同时换掉【置顶】【最近】【项目】会话行与【项目】工作区块头四张卡。
   **宽度不改在这条之外**：Menu 的宽度是它自己那两个数（min-w 218 / max-w 360），与本卡不同源。

   这里只管**卡内**，且这几条同时喂四处（本包两区的 regions.tsx + 补丁渲的项目区两处），故：
   ① 选择器一律带 [data-tpt-hover-content] 前缀：特异性 (0,2,0)，与注入顺序无关地压过上游 CSS module
      的 .hoverTitle / .hoverPath（(0,1,0)，而那张表可能晚于我方 sheet 注入 —— 顺序是最脆的契约）；
   ② 颜色全部 token。八改版那批硬编码（#fff / #cfd3d6 / #adb2b8）是给"恒定深底"写的，外壳换成 popover
      后就是白底白字。对位关系：标题 = --dsw-alias-label-primary，次级三行 = --dsw-alias-label-secondary
      （= Menu 卡里 label/icon 那枚 text-muted-foreground 的同值蓝本），分割线 = --border
      （= Menu 那条 separator 的 bg-border，经 --color-border 映射到同一个 CSS 变量）。
   ③ 标题/项目行**单行省略号**（用户口径「标题过长溢出省略号展示」），文件夹路径行仍 word-break: break-all
      —— 那条的完整内容才是有用信息，卡上点一下即整条复制（copyText 走 HoverCard 的复制分支）。 */
[data-tpt-hover-content]{
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}
[data-tpt-hover-content] [data-tpt-hover-title]{
  color: var(--dsw-alias-label-primary);
  font-size: 14px;
  line-height: 20px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
[data-tpt-hover-content] [data-tpt-hover-workspace]{
  color: var(--dsw-alias-label-secondary);
  font-size: 12px;
  line-height: 16px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
[data-tpt-hover-content] [data-tpt-hover-count]{
  color: var(--dsw-alias-label-secondary);
  font-size: 12px;
  line-height: 16px;
}
[data-tpt-hover-content] [data-tpt-hover-path]{
  color: var(--dsw-alias-label-secondary);
  word-break: break-all;
  font-size: 12px;
  line-height: 16px;
}
[data-tpt-hover-content] [data-tpt-hover-time]{
  color: var(--dsw-alias-label-secondary);
  font-size: 12px;
  line-height: 16px;
}
/* 组内那句「暂无任务」（某个【项目】的会话**全部**被置顶时出现的那一行，四十一改版落地、四十二改版改口）：
   它是**会话行的替身** => 左边 30px = 会话行文本左缘（上游 .YDXeBa_sessionRow 的 padding:0 8px + 首格
   图标 16px + gap 6px = 30，四十二改版推导、当时未实测）。纵向归零 = 用户 2026-09-16 口径「去掉 padding，
   只保留左侧 30px」（上游 .empty 原本是 padding: 16px 12px）。
   选择器带 [role="tree"] 前缀 = 特异性 (0,2,0)，与注入顺序无关地压过上游 CSS module 的 .xxxx_empty
   （(0,1,0)）—— 同上面 [data-tpt-hover-content] 那一族的手法，别去掉前缀"简化"成一条属性选择器。
   只打在组内那一行上：整列空态与平铺档空态**共用**那个 .empty 类但不带这个属性，它们的 padding 保持上游
   原样（那两处没有"要和会话行的文本对位"这件事）。
   [!] 四十四改版曾把那颗「展开剩余 N 个项目 / 收起」并进这一条（按用户当时那句「边距样式和暂无任务一样」的
   字面口径），四十六改版**又拆开了** —— 原因与真读数在下面那条独立规则里，别顺手"去重"合并回去。 */
[role="tree"] [data-tpt-workspace-empty]{
  padding: 0 0 0 30px;
}
/* 那颗「展开剩余 N 个项目 / 收起」（四十五改版，用户 2026-09-17 原话：「应该和工作区/文件夹左对齐，不能和
   【暂无任务】一样的边距，否则会有歧义，认为是收起文件夹内的会话」）。
   左内边距取 **8px** = 上游文件夹行同值（真读数取自 temp/served-combo-real-v33.js 那张运行期 combo：
   .YDXeBa_projectRow,.YDXeBa_sessionRow{...gap:6px;padding:0 8px;display:flex}；同一张里那颗上游件原本是
   .bhn1Oq_sessionOverflowButton{...padding:0 12px 0 28px}，那 28px 是给它自己**组内**那个位置对位用的）。
   为什么 30px 是错的（这批唯一的设计判断，别再改回去）：**两层的层级不同**。上游那颗住在 groupSection
   **里面**，收的是"这个文件夹里被挡住的会话"，30px 正好落在会话文本那一格；我方这颗住在**项目列表**那一层
   （与 groupSection 平级，父层 .bhn1Oq_treeBody 无内边距），收的是**项目文件夹本身** => 沿用 30px 等于用
   缩进宣称"我是某文件夹里的一条会话"，用户读到的正是这个歧义。左右都取 8px 还带一个连带好处：那颗的 hover
   底色（28px 高 / r8）与文件夹行的 hover 底色（34px 高 / r8）左右缘同宽，两块药丸看着是同一族。
   特异性 (0,2,0) 照旧压过上游 .xxxx_sessionOverflowButton 的 (0,1,0) => 与注入顺序无关。 */
[role="tree"] [data-tpt-projects-overflow]{
  padding: 0 8px;
}
/* 会话行：数字照抄上游会话行（32px / r8 / 标题 ellipsis / 时间 tertiary 12px）。
   二十三改版需求 3（用户：「【置顶】和【最近】里的会话不用和【项目】一样开头留白，直接和标题对齐，
   这样可以展示更多的内容」）：左内边距从 8px 收到 **4px** —— 与我方表头的 padding-left 4px 同一个值，
   于是"无状态行的标题文本左缘"就落在面板标题文字那条竖线上（实测：改版前标题文本 x=42、缩进 30，改版后 x=16
   = 面板标题左缘 = 行左缘 12 + padding 4）。右内边距保持 8px：那是行 hover 底色的右侧留白，与左边的
   对齐无关，别一起改。对齐的另一半（空状态槽塌掉、标题自带 margin 归零）在下面两条。 */
[data-tpt-region-row]{
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 8px 0 4px;
  border-radius: 8px;
  color: var(--dsw-alias-label-primary);
  font-size: 14px;
  line-height: 20px;
  cursor: pointer;
}
[data-tpt-region-row]:hover{
  background: var(--dsw-alias-interactive-bg-hover);
}
[data-tpt-region-row]:focus-visible{
  outline: 1px solid var(--dsw-alias-border-l3);
  outline-offset: -1px;
}
[data-tpt-region-row][data-tpt-region-current="true"]{
  background: var(--dsw-alias-interactive-bg-hover);
}
/* 空态行（四十七改版：最近区无候选时不再整块隐藏，展开留一行「暂无任务」；置顶区不做）。
   左内边距与 [data-tpt-region-row] 同值（4px）=> 文案左缘落在面板标题那条竖线（x=16）上，与有会话
   时的行标题同一条竖线；改 30px 就是错位（那 30px 是【项目】树里组内那句的专用值，场景不同，别照抄）。
   字号与字色照【项目】组内那句（八改版，用户 2026-09-22 口径「和【项目】折叠面板中的暂无任务样式保持
   一致」，当场确认口径 = **只统一文字**）=> 与上游 .xxxx_empty 同值：--dsw-alias-label-tertiary + 13px
   （改版前是本包的 secondary + 14px，两处并排看着深浅、大小都不一样）。缩进与 32px 行高**不动**：
   那是"会话行替身"的姿态（本地口径，上游 .empty 无此物），统一它会让空态比其他行矮一截、并缩进成
   树里会话那一格。【项目】那句的内边距由上面那条独立规则单管（注意：那条选择器在本表里只许出现一次，
   注释里也别把它抄进来 —— 有门禁数它的出现次数）。 */
[data-tpt-region-empty]{
  box-sizing: border-box;
  display: flex;
  align-items: center;
  height: 32px;
  padding: 0 8px 0 4px;
  color: var(--dsw-alias-label-tertiary);
  font-size: 13px;
  line-height: 20px;
  user-select: none;
}
/* 状态槽（三十五改版）：整颗 span 平时**不渲**（见 regions.tsx 的 view.slot !== null），所以这里
   不需要 :empty 塌槽那套 —— 行有 gap，留一个空壳照样吃掉一份 gap，DOM 里也不该有"存在但不可见"
   的行内件。这里只管渲出来时候的样子：点位与 hover 底色的关系照上游 .slot / .time（16 高、tertiary 色）。 */
/* 标题：二十三改版需求 3 起**不自带 margin**，左缘落在面板标题那条竖线上（x=16）。
   三十五改版把行首那颗状态槽整个删了，标题因此直接顶到行左内边距（4px），右侧那一格换到行尾。 */
[data-tpt-region-row-title]{
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
/* hover 跑马灯（六十一改版）：标题过长时，鼠标悬浮所在行 → 横向循环滚动把全文读完（移开复位）。
   JS 见 title-marquee.ts（按 scrollLeft 逐帧推进，三区统一走委托）。这里两条**只是兜底**：
   text-overflow:clip（跑动时再画省略号会闪；上游 sessionRow:hover 本来就给 clip，这里对三区统一）；
   scroll-behavior:auto —— 【注意】上游给会话行标题写的是 类名组合 .X_sessionRow .X_title 上的
   scroll-behavior:smooth，权重 (0,2,0) 压过本条的 (0,1,0) → **真正管用的是控制器写的行内样式**，
   本条只对没有上游规则的那几处（我方两区标题、文件夹名）生效。别删了行内那行，只留这条会退化回
   "几乎不动"。注意：本段在一个模板字符串里 —— 不许出现反引号，也不许出现箭头这类图标性字形。 */
[data-tpt-title-marquee]{
  scroll-behavior: auto;
  text-overflow: clip;
}
[data-tpt-region-row-status]{
  flex: none;
  display: inline-flex;
  align-items: center;
  height: 20px;
  color: var(--dsw-alias-label-tertiary);
}
/* 读屏文案：点本体 aria-hidden，靠这一颗给可访问名（上游 .visuallyHidden 同一手法：clip + 1px，
   不用 display:none —— 后者会被无障碍树整棵摘掉，等于没写）。 */
[data-tpt-region-row-status-label]{
  position: absolute;
  width: 1px;
  height: 1px;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  overflow: hidden;
}
/* ── 行尾那一格：状态 <-> 图标簇互换（三十五改版沿用二十五改版的 hover 语法，用户 2026-09-15/16）───
   平时只有那一格（时间已经彻底不上屏，换成加载态/未读点），整簇图标 display:none -> 不占位。
   改版前那颗取消置顶钮是"常驻 20px + opacity 开关"，其右侧因此永远空着 20px + 6px gap —— 那就是
   用户当年要消掉的"时间右边距"。hover / 键盘聚焦 / 菜单开着才让位给图标簇，做法与判据照上游
   【项目】那行（上游 CSS：rowActions 平时 display:none、hover 才 inline-flex，且 sessionRow:hover
   把 .time 收成 none —— 我方这一格顶的就是 .time 那个位置）。
   focus-visible 那条是**键盘入口**：簇不显示就 tab 不进去 -> 行自己拿到键盘焦点时先把簇显出来，
   下一次 Tab 才落在钮上（显出来后 focus-within 接手）。标题是 flex:1，换上来的是 16px 图标，
   宽度差全由标题吃掉 -> 换格不跳行（与上游同因）。
   注意：本段在一个模板字符串里，整段不许出现反引号（它会把字符串关掉，报一串 TS1005），
   也不许出现箭头/警告这类图标性字形（tpt/icon-glyph 把字符串内容也算进编译产物）。 */
[data-tpt-region-row-actions]{
  display: none;
  flex: none;
  align-items: center;
  gap: 12px;
}
[data-tpt-region-row]:hover [data-tpt-region-row-status],
[data-tpt-region-row]:focus-within [data-tpt-region-row-status],
[data-tpt-region-row]:focus-visible [data-tpt-region-row-status],
[data-tpt-region-row][data-tpt-region-menu-open="true"] [data-tpt-region-row-status]{
  display: none;
}
[data-tpt-region-row]:hover [data-tpt-region-row-actions],
[data-tpt-region-row]:focus-within [data-tpt-region-row-actions],
[data-tpt-region-row]:focus-visible [data-tpt-region-row-actions],
[data-tpt-region-row][data-tpt-region-menu-open="true"] [data-tpt-region-row-actions]{
  display: inline-flex;
}
/* 菜单开着时行保持 hover 底色（上游 sessionRow.menuOpen 同款：菜单在 portal 里，鼠标移进去
